import { SignJWT, importJWK } from 'jose'

/**
 * Mint a short-lived Supabase Realtime access JWT for a logged-in user.
 *
 * We keep our own auth in nuxt-auth-utils; Supabase has no record of our users.
 * This token is purely a Realtime access ticket: Supabase Realtime authenticates
 * the websocket by verifying this JWT against the ES256 signing key registered in
 * the project (matched by `kid`). It reads the `role` claim to pick the Postgres
 * role.
 *
 * The signing key is a JWK (JSON Web Key) — generated by `supabase gen
 * signing-key --algorithm ES256`, imported into the Supabase dashboard so it can
 * verify, and held by us (in env) so we can sign. The JWK's own `kid` field ties
 * a signed token to the registered key, so we don't take a separate kid param.
 *
 * Required claims (per Supabase signing-keys docs): `sub`, `role: 'authenticated'`,
 * `exp`. We also set `iss` + `iat` by convention. The protected header carries
 * `alg: ES256` and `kid` so Supabase selects the right key.
 *
 * @param {object} params
 * @param {string} params.userId - our user id → JWT `sub`
 * @param {object|string} params.privateJwk - ES256 private key as a JWK (object or
 *   JSON string). Must include a `kid`.
 * @param {number} [params.ttlSeconds=3600] - token lifetime (default 1h)
 * @returns {Promise<{ token: string, expiresAt: number }>} expiresAt = unix seconds
 */
export async function mintRealtimeToken ({ userId, privateJwk, ttlSeconds = 3600 }) {
  if (!userId) {
    throw new Error('mintRealtimeToken: userId is required')
  }
  if (!privateJwk) {
    throw new Error('mintRealtimeToken: privateJwk is required')
  }

  const jwk = typeof privateJwk === 'string' ? JSON.parse(privateJwk) : privateJwk

  if (!jwk.kid) {
    throw new Error('mintRealtimeToken: privateJwk must include a kid')
  }

  const privateKey = await importJWK(jwk, 'ES256')

  const nowSeconds = Math.floor(Date.now() / 1000)
  const expiresAt = nowSeconds + ttlSeconds

  const token = await new SignJWT({ role: 'authenticated' })
    .setProtectedHeader({ alg: 'ES256', kid: jwk.kid, typ: 'JWT' })
    .setSubject(userId)
    .setIssuer('tally-split')
    .setIssuedAt(nowSeconds)
    .setExpirationTime(expiresAt)
    .sign(privateKey)

  return { token, expiresAt }
}
